'use client';

import { AnimatePresence, motion, type Variants } from 'motion/react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { useSession } from '@/registry/ndeko/hooks/use-session';
import { useTimeouts } from '@/registry/ndeko/hooks/use-timeouts';
import {
  pressedQuietOf,
  spokenUnless,
} from '@/registry/ndeko/lib/demonstration';
import { InboxIcon } from '@/registry/ndeko/lib/icons';
import {
  EASE_OUT_STRONG,
  risePresenceOf,
  SPRING,
} from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';
import { CompanyMark } from '@/registry/ndeko/ui/company-mark';
import { ClockGate } from '@/registry/ndeko/ui/live-duration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';

import { ChecklistCard } from './checklist-card';
import { STEPS, WORKSPACE, type StepId } from './data';
import { ProgressRing } from './progress-ring';
import {
  COMPLETE_FOR_MS,
  INITIAL,
  LOOP_AFTER_MS,
  reducer,
  RESTING,
  SCRIPT,
  TOTAL,
  type ChecklistState,
} from './session';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

/** How the card leaves: folded into its pill, closed by a person, or faded once everything is done. */
type Leaving = 'fold' | 'close' | 'fade';

const FOLD_AWAY = {
  opacity: 0,
  scale: 0.6,
  transition: { duration: 0.18, ease: EASE_OUT_STRONG },
};

const CLOSE = {
  opacity: 0,
  scale: 0.96,
  transition: { duration: 0.14, ease: EASE_OUT_STRONG },
};

const FADE_AWAY = { opacity: 0, transition: { duration: 0.5 } };

function exitOf(leaving: Leaving) {
  if (leaving === 'fold') {
    return FOLD_AWAY;
  }
  if (leaving === 'fade') {
    return FADE_AWAY;
  }
  return CLOSE;
}

const CARD: Variants = {
  hidden: { opacity: 0, scale: 0.96 },
  shown: { opacity: 1, scale: 1, transition: SPRING },
  gone: exitOf,
};

const PILL: Variants = {
  hidden: { opacity: 0, scale: 0.8 },
  shown: { opacity: 1, scale: 1, transition: SPRING },
  gone: CLOSE,
};

/** Reduced motion keeps the fades and drops the folding. */
const STILL: Variants = {
  hidden: { opacity: 0 },
  shown: { opacity: 1 },
  gone: { opacity: 0 },
};

function variantsOf(shouldReduceMotion: boolean, variants: Variants) {
  if (shouldReduceMotion) {
    return STILL;
  }
  return variants;
}

function leavingOf(state: ChecklistState): Leaving {
  if (state.view === 'pill') {
    return 'fold';
  }
  const isAllDone = state.done.length === TOTAL;
  if (isAllDone) {
    return 'fade';
  }
  return 'close';
}

/** The step after this one, which opens when this one is done. */
function stepAfter(id: StepId) {
  const index = STEPS.findIndex((step) => step.id === id);
  const next = STEPS[index + 1];
  return next?.id ?? null;
}

export default function Onboarding01() {
  const {
    ref,
    isInView,
    isAutoplaying,
    state,
    act,
    pressed,
    isFinished,
    restart,
  } = useSession(SESSION);
  const { schedule, clearAll } = useTimeouts();
  const shouldReduceMotion = usePrefersReducedMotion();
  const guidePresence = risePresenceOf(shouldReduceMotion);
  const doneCount = state.done.length;
  const isComplete = state.view === 'complete';
  const showsCard = state.view === 'card' || isComplete;
  const showsPill = state.view === 'pill';
  const isPutAway = state.view === 'gone';
  const leaving = leavingOf(state);
  const message = spokenUnless(isAutoplaying, state.spoken);
  const canReplay = isFinished && !isAutoplaying;

  function focusLater(selector: string) {
    requestAnimationFrame(() => {
      const target = ref.current?.querySelector<HTMLElement>(selector);
      target?.focus();
    });
  }

  /** The button of the current step when there is one, the first step otherwise. */
  function focusGuide() {
    requestAnimationFrame(() => {
      const root = ref.current;
      const action = root?.querySelector<HTMLElement>('[data-step-cta]');
      const firstRow = root?.querySelector<HTMLElement>('[data-step-row]');
      const target = action ?? firstRow;
      target?.focus();
    });
  }

  /** The message leaves on its own: a focus that sat on it goes to the button that brings the guide back. */
  function fadeCompletion() {
    const completion = ref.current?.querySelector('[data-complete]');
    const hadFocus = completion === document.activeElement;
    act({ type: 'completionFaded', source: 'person' });
    if (completion && hadFocus) {
      focusLater('[data-setup-guide]');
    }
  }

  /** The button that was pressed folds away with its step, so the focus goes to the button of the next one. */
  function complete(id: StepId) {
    const nextId = stepAfter(id);
    act({ type: 'stepCompleted', id, source: 'person' });
    if (nextId === null) {
      focusLater('[data-complete]');
      schedule(fadeCompletion, COMPLETE_FOR_MS);
      return;
    }
    focusLater(`[data-step-cta="${nextId}"]`);
  }

  function snooze() {
    act({ type: 'snoozed' });
    focusLater('[data-pill]');
  }

  function resume() {
    act({ type: 'resumed' });
    focusGuide();
  }

  function dismiss() {
    act({ type: 'dismissed' });
    focusLater('[data-setup-guide]');
  }

  /** A message that waits to fade belongs to the round it came up in. */
  function replay() {
    clearAll();
    restart();
  }

  return (
    <ClockGate isActive={isInView}>
      <div
        ref={ref}
        className='bg-background text-foreground @container relative flex min-h-dvh w-full flex-col'
      >
        <header className='flex h-14 shrink-0 items-center gap-2.5 px-4'>
          <CompanyMark seed={WORKSPACE.name} size='lg' />
          <p className='min-w-0 flex-1 truncate text-sm font-medium'>
            {WORKSPACE.name}
          </p>
          <ReplayButton isShown={canReplay} onReplay={replay} label='Replay' />
          <AnimatePresence initial={false}>
            {isPutAway && (
              <motion.span
                key='setup-guide'
                className='inline-flex'
                {...guidePresence}
              >
                <Button
                  type='button'
                  variant='outline'
                  size='sm'
                  data-setup-guide
                  onClick={resume}
                >
                  Setup guide
                  <span className='text-muted-foreground tabular-nums'>
                    {doneCount} of {TOTAL}
                  </span>
                </Button>
              </motion.span>
            )}
          </AnimatePresence>
        </header>

        <main className='flex flex-1 flex-col gap-4 p-4 pt-2 @md:px-6'>
          <h1 className='text-lg font-semibold'>Home</h1>
          <div className='hairline-border border-foreground/20 flex flex-col items-start gap-2 rounded-xl border-dashed p-5'>
            <span
              aria-hidden='true'
              className='keycap-3d text-muted-foreground mb-1 inline-flex size-10 items-center justify-center rounded-lg'
            >
              <InboxIcon className='size-5' />
            </span>
            <p className='text-sm font-medium'>No agent has run yet</p>
            <p className='text-muted-foreground max-w-sm text-[13px] leading-relaxed text-pretty'>
              Runs, requests and results show up on this page once your first
              agent has done its first job
            </p>
          </div>
        </main>

        <div className='pointer-events-none absolute inset-x-3 bottom-3 z-10 flex justify-end @md:inset-x-auto @md:end-4 @md:bottom-4'>
          <AnimatePresence initial={false} mode='popLayout' custom={leaving}>
            {showsCard && (
              <motion.section
                key='card'
                aria-label='Setup guide'
                variants={variantsOf(shouldReduceMotion, CARD)}
                custom={leaving}
                initial='hidden'
                animate='shown'
                exit='gone'
                className='surface-raised pointer-events-auto w-full origin-bottom-right rounded-xl @md:w-[22rem]'
              >
                <ChecklistCard
                  done={state.done}
                  openId={state.openId}
                  howToId={state.howToId}
                  isComplete={isComplete}
                  pressed={pressed}
                  onToggle={(id) => act({ type: 'stepToggled', id })}
                  onToggleHowTo={(id) => act({ type: 'howToToggled', id })}
                  onComplete={complete}
                  onSnooze={snooze}
                  onDismiss={dismiss}
                />
              </motion.section>
            )}
            {showsPill && (
              <motion.button
                key='pill'
                type='button'
                data-pill
                aria-label={`Open the setup guide: ${doneCount} of ${TOTAL} steps done`}
                variants={variantsOf(shouldReduceMotion, PILL)}
                initial='hidden'
                animate='shown'
                exit='gone'
                onClick={resume}
                className={cn(
                  'surface-raised focus-visible:ring-ring pointer-events-auto flex h-9 origin-bottom-right cursor-pointer items-center gap-2 rounded-full ps-2 pe-3.5 text-xs font-medium transition-[background-color,scale] duration-150 outline-none focus-visible:ring-2',
                  pressedQuietOf(pressed === 'pill')
                )}
              >
                <ProgressRing done={doneCount} total={TOTAL} size='sm' />
                Setup
                <span className='text-muted-foreground tabular-nums'>
                  {doneCount} of {TOTAL}
                </span>
              </motion.button>
            )}
          </AnimatePresence>
        </div>
        <LiveRegion message={message} />
      </div>
    </ClockGate>
  );
}

'use client';

import { useId } from 'react';

import { MotionNumber } from '@/components/core/motion-number';
import {
  pressedQuietOf,
  pressedSolidOf,
} from '@/registry/ndeko/lib/demonstration';
import { ChevronDownIcon, LockIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';
import { Fold, Swap } from '@/registry/ndeko/ui/chat-motion';
import { DrawnCheck } from '@/registry/ndeko/ui/drawn-check';

import { CalmCheck } from './calm-check';
import { STEPS, WORKSPACE, type SetupStep, type StepId } from './data';
import { ProgressRing } from './progress-ring';
import { statusOf, TOTAL, type StepStatus } from './session';

const NUMBER =
  'inline-flex size-[18px] items-center justify-center rounded-full text-[11px] leading-none font-medium tabular-nums';

const ROW =
  'focus-visible:ring-ring/25 flex h-10 w-full items-center gap-2.5 rounded-lg px-2 text-start outline-none transition-colors duration-150 focus-visible:ring-[3px]';

const HOW_TO_TOGGLE =
  'text-primary-ink focus-visible:ring-ring/25 -mx-1 flex h-6 w-fit cursor-pointer items-center gap-1 rounded-sm px-1 text-xs font-medium outline-none transition-[background-color,scale] duration-150 hover:bg-foreground/[0.05] focus-visible:ring-[3px]';

function rowToneOf(status: StepStatus) {
  if (status === 'locked') {
    return 'text-muted-foreground cursor-not-allowed';
  }
  return 'hover:bg-foreground/[0.04] cursor-pointer';
}

function chevronTurnOf(isOpen: boolean) {
  if (isOpen) {
    return 'rotate-180';
  }
  return 'rotate-0';
}

function stepsLeftLineOf(left: number) {
  if (left === 0) {
    return 'Every step is done';
  }
  if (left === 1) {
    return '1 step left';
  }
  return `${left} steps left`;
}

type StepMarkProps = {
  status: StepStatus;
  number: number;
};

/** The number becomes a check when the step is done. Steps that are done when the page loads show their check at once. */
function StepMark({ status, number }: StepMarkProps) {
  return (
    <Swap swapKey={status} className='size-[18px] shrink-0 justify-center'>
      {status === 'done' && (
        <DrawnCheck tone='success' entrance='draw' pace='calm' />
      )}
      {status === 'current' && (
        <span className={cn(NUMBER, 'bg-primary text-primary-foreground')}>
          {number}
        </span>
      )}
      {status === 'locked' && (
        <span
          className={cn(NUMBER, 'bg-foreground/[0.06] text-muted-foreground')}
        >
          {number}
        </span>
      )}
    </Swap>
  );
}

type StepRowProps = {
  step: SetupStep;
  number: number;
  status: StepStatus;
  isOpen: boolean;
  isHowToOpen: boolean;
  pressed: string | null;
  onToggle: (id: StepId) => void;
  onToggleHowTo: (id: StepId) => void;
  onComplete: (id: StepId) => void;
};

function StepRow({
  step,
  number,
  status,
  isOpen,
  isHowToOpen,
  pressed,
  onToggle,
  onToggleHowTo,
  onComplete,
}: StepRowProps) {
  const bodyId = useId();
  const howToId = useId();
  const isLocked = status === 'locked';
  const isCurrent = status === 'current';
  const hasAction = isCurrent && step.action !== undefined;

  return (
    <li>
      <button
        type='button'
        data-step-row={step.id}
        aria-expanded={isOpen}
        aria-controls={bodyId}
        disabled={isLocked}
        onClick={() => onToggle(step.id)}
        className={cn(ROW, rowToneOf(status))}
      >
        <StepMark status={status} number={number} />
        <span className='min-w-0 flex-1 truncate text-[13px] font-medium'>
          {step.title}
        </span>
        {isLocked && (
          <LockIcon aria-hidden='true' className='size-3.5 shrink-0' />
        )}
        {isLocked && <span className='sr-only'>Locked</span>}
        {!isLocked && (
          <ChevronDownIcon
            aria-hidden='true'
            className={cn(
              'text-muted-foreground size-3.5 shrink-0 transition-[rotate] duration-200 ease-(--ease-out-strong)',
              chevronTurnOf(isOpen)
            )}
          />
        )}
      </button>
      <Fold open={isOpen} id={bodyId}>
        <div className='flex flex-col items-start gap-2.5 ps-[2.375rem] pe-2 pb-2.5'>
          <p className='text-muted-foreground text-xs leading-5 text-pretty'>
            {step.detail}
          </p>
          {step.howTo && (
            <div className='flex w-full flex-col'>
              <button
                type='button'
                aria-expanded={isHowToOpen}
                aria-controls={howToId}
                onClick={() => onToggleHowTo(step.id)}
                className={cn(
                  HOW_TO_TOGGLE,
                  pressedQuietOf(pressed === `howto-${step.id}`)
                )}
              >
                How it works
                <ChevronDownIcon
                  aria-hidden='true'
                  className={cn(
                    'size-3.5 transition-[rotate] duration-200 ease-(--ease-out-strong)',
                    chevronTurnOf(isHowToOpen)
                  )}
                />
              </button>
              <Fold open={isHowToOpen} id={howToId}>
                <ol className='text-muted-foreground flex list-decimal flex-col gap-1 ps-4 pt-1.5 text-xs leading-5 marker:tabular-nums'>
                  {step.howTo.map((line) => (
                    <li key={line} className='ps-0.5'>
                      {line}
                    </li>
                  ))}
                </ol>
              </Fold>
            </div>
          )}
          {hasAction && (
            <Button
              type='button'
              size='sm'
              data-step-cta={step.id}
              onClick={() => onComplete(step.id)}
              className={pressedSolidOf(pressed === `cta-${step.id}`)}
            >
              {step.action}
            </Button>
          )}
        </div>
      </Fold>
    </li>
  );
}

type RevealProps = {
  isOpen: boolean;
  children: React.ReactNode;
};

function rowsOf(isOpen: boolean) {
  if (isOpen) {
    return 'grid-rows-[1fr] opacity-100';
  }
  return 'grid-rows-[0fr] opacity-0';
}

/**
 * A part of the card that opens to the height of what it holds. The row of a grid does it, so the
 * steps inside keep folding at their own pace without a second measure chasing them.
 */
function Reveal({ isOpen, children }: RevealProps) {
  return (
    <div
      className={cn(
        'grid transition-[grid-template-rows,opacity] duration-300 ease-(--ease-out-strong)',
        rowsOf(isOpen)
      )}
    >
      <div inert={!isOpen} className='min-h-0 overflow-hidden'>
        {children}
      </div>
    </div>
  );
}

export type ChecklistCardProps = {
  done: StepId[];
  openId: StepId | null;
  howToId: StepId | null;
  /** Every step is done and the card says so before it leaves. */
  isComplete: boolean;
  pressed: string | null;
  onToggle: (id: StepId) => void;
  onToggleHowTo: (id: StepId) => void;
  onComplete: (id: StepId) => void;
  onSnooze: () => void;
  onDismiss: () => void;
};

/** The card closes over its steps and opens on its closing message: it is the same card, saying something shorter. */
export function ChecklistCard({
  done,
  openId,
  howToId,
  isComplete,
  pressed,
  onToggle,
  onToggleHowTo,
  onComplete,
  onSnooze,
  onDismiss,
}: ChecklistCardProps) {
  const headingId = useId();
  const doneCount = done.length;
  const left = TOTAL - doneCount;

  return (
    <>
      <Reveal isOpen={isComplete}>
        {isComplete && (
          <div
            data-complete
            tabIndex={-1}
            className='flex items-center gap-3 p-4 outline-none'
          >
            <CalmCheck />
            <div className='flex min-w-0 flex-col gap-0.5'>
              <p className='text-sm font-medium'>{WORKSPACE.name} is set up</p>
              <p className='text-muted-foreground text-xs text-pretty'>
                This guide stays under Setup guide in the top bar
              </p>
            </div>
          </div>
        )}
      </Reveal>
      <Reveal isOpen={!isComplete}>
        <header className='flex items-center gap-3 p-3.5 pb-2'>
          <ProgressRing done={doneCount} total={TOTAL}>
            <MotionNumber
              value={doneCount}
              className='text-xs leading-none font-semibold'
            />
          </ProgressRing>
          <div className='flex min-w-0 flex-1 flex-col gap-0.5'>
            <h2 id={headingId} className='truncate text-sm font-medium'>
              Set up {WORKSPACE.name}
            </h2>
            <p className='text-muted-foreground text-xs tabular-nums'>
              <span className='sr-only'>
                {doneCount} of {TOTAL} steps done.{' '}
              </span>
              {stepsLeftLineOf(left)}
            </p>
          </div>
        </header>
        <ol aria-labelledby={headingId} className='flex flex-col px-1.5'>
          {STEPS.map((step, index) => (
            <StepRow
              key={step.id}
              step={step}
              number={index + 1}
              status={statusOf(done, step.id)}
              isOpen={openId === step.id}
              isHowToOpen={howToId === step.id}
              pressed={pressed}
              onToggle={onToggle}
              onToggleHowTo={onToggleHowTo}
              onComplete={onComplete}
            />
          ))}
        </ol>
        <footer className='flex items-center justify-end gap-1 p-1.5 pt-1'>
          <Button
            type='button'
            variant='ghost'
            size='sm'
            data-snooze
            onClick={onSnooze}
            className={cn(
              'text-muted-foreground',
              pressedQuietOf(pressed === 'snooze')
            )}
          >
            Snooze
          </Button>
          <Button
            type='button'
            variant='ghost'
            size='sm'
            onClick={onDismiss}
            className='text-muted-foreground'
          >
            Dismiss
          </Button>
        </footer>
      </Reveal>
    </>
  );
}

import { cn } from '@/registry/ndeko/lib/utils';

export type ProgressRingSize = 'sm' | 'md';

const SIZE_CLASS: Record<ProgressRingSize, string> = {
  sm: 'size-5',
  md: 'size-9',
};

const STROKE_WIDTH: Record<ProgressRingSize, number> = {
  sm: 5,
  md: 3,
};

const VIEW = 36;

const CENTRE = VIEW / 2;

const RADIUS = 15;

const CIRCUMFERENCE = 2 * Math.PI * RADIUS;

/** The part of the ring that stays empty. No step yet counts as nothing done. */
function emptyLengthOf(done: number, total: number) {
  if (total <= 0) {
    return CIRCUMFERENCE;
  }
  const share = Math.min(1, done / total);
  return CIRCUMFERENCE * (1 - share);
}

type ProgressRingProps = {
  done: number;
  total: number;
  size?: ProgressRingSize;
  className?: string;
  /** What sits in the middle of the ring: a count, or nothing. */
  children?: React.ReactNode;
};

/**
 * A ring that fills as steps are done. The stroke eases to its new length once per step, which is
 * the only time it is painted again. With nothing done the stroke is hidden: a round cap would
 * leave a dot.
 */
export function ProgressRing({
  done,
  total,
  size = 'md',
  className,
  children,
}: ProgressRingProps) {
  const strokeWidth = STROKE_WIDTH[size];
  const isEmpty = done <= 0;

  return (
    <span
      className={cn(
        'relative inline-flex shrink-0 items-center justify-center',
        SIZE_CLASS[size],
        className
      )}
    >
      <svg
        aria-hidden='true'
        viewBox={`0 0 ${VIEW} ${VIEW}`}
        className='absolute inset-0 size-full -rotate-90'
      >
        <circle
          cx={CENTRE}
          cy={CENTRE}
          r={RADIUS}
          fill='none'
          strokeWidth={strokeWidth}
          className='stroke-foreground/10'
        />
        <circle
          cx={CENTRE}
          cy={CENTRE}
          r={RADIUS}
          fill='none'
          strokeWidth={strokeWidth}
          strokeLinecap='round'
          strokeDasharray={CIRCUMFERENCE}
          strokeDashoffset={emptyLengthOf(done, total)}
          className={cn(
            'stroke-primary transition-[stroke-dashoffset] duration-500 ease-(--ease-out-strong)',
            isEmpty && 'invisible'
          )}
        />
      </svg>
      {children}
    </span>
  );
}

'use client';

import { motion } from 'motion/react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { EASE_OUT_STRONG } from '@/registry/ndeko/lib/motion-presets';

const CHECK_PATH = 'M2.6 6.4 4.9 8.7 9.5 3.6';

const DRAW = { duration: 0.32, ease: EASE_OUT_STRONG, delay: 0.1 };

const DRAWN = { pathLength: 1 };

const NOT_DRAWN = { pathLength: 0 };

function strokeStartOf(shouldReduceMotion: boolean) {
  if (shouldReduceMotion) {
    return DRAWN;
  }
  return NOT_DRAWN;
}

/** The larger mark of the message that says every step is done. Reduced motion shows it drawn. */
export function CalmCheck() {
  const shouldReduceMotion = usePrefersReducedMotion();

  return (
    <span className='bg-success/10 text-success-foreground flex size-10 shrink-0 items-center justify-center rounded-full'>
      <svg aria-hidden='true' viewBox='0 0 12 12' className='size-5'>
        <motion.path
          d={CHECK_PATH}
          fill='none'
          stroke='currentColor'
          strokeWidth={1.4}
          strokeLinecap='round'
          strokeLinejoin='round'
          initial={strokeStartOf(shouldReduceMotion)}
          animate={DRAWN}
          transition={DRAW}
        />
      </svg>
    </span>
  );
}

import type { SessionStep } from '@/registry/ndeko/hooks/use-session';

import { DONE_AT_FIRST, stepOf, STEPS, WORKSPACE, type StepId } from './data';

/** The guide is a card, a pill once snoozed, a short message once every step is done, or put away. */
export type View = 'card' | 'pill' | 'complete' | 'gone';

export type Source = 'demo' | 'person';

export type StepStatus = 'done' | 'current' | 'locked';

export type ChecklistState = {
  /** The steps that are done, in the order they were done. */
  done: StepId[];
  openId: StepId | null;
  /** The how-to that is unfolded inside the open step. */
  howToId: StepId | null;
  view: View;
  /** Who did the last step: the message that follows only fades for the one who brought it up. */
  completedBy: Source | null;
  spoken: string;
};

export type ChecklistAction =
  | { type: 'stepToggled'; id: StepId }
  | { type: 'howToToggled'; id: StepId }
  | { type: 'stepCompleted'; id: StepId; source: Source }
  | { type: 'snoozed' }
  | { type: 'resumed' }
  | { type: 'dismissed' }
  | { type: 'completionFaded'; source: Source };

type Step = SessionStep<ChecklistState, ChecklistAction>;

export const TOTAL = STEPS.length;

/** The steps are done in order: the first one that is not done is the current one. */
export function currentOf(done: StepId[]) {
  const current = STEPS.find((step) => !done.includes(step.id));
  return current?.id ?? null;
}

export function statusOf(done: StepId[], id: StepId): StepStatus {
  if (done.includes(id)) {
    return 'done';
  }
  if (currentOf(done) === id) {
    return 'current';
  }
  return 'locked';
}

export const INITIAL: ChecklistState = {
  done: DONE_AT_FIRST,
  openId: currentOf(DONE_AT_FIRST),
  howToId: null,
  view: 'card',
  completedBy: null,
  spoken: '',
};

function stepToggled(state: ChecklistState, id: StepId): ChecklistState {
  const isLocked = statusOf(state.done, id) === 'locked';
  if (isLocked) {
    return state;
  }
  if (state.openId === id) {
    return { ...state, openId: null, howToId: null };
  }
  return { ...state, openId: id, howToId: null };
}

function howToToggled(state: ChecklistState, id: StepId): ChecklistState {
  if (state.openId !== id) {
    return state;
  }
  if (state.howToId === id) {
    return { ...state, howToId: null };
  }
  return { ...state, howToId: id };
}

/** Doing the current step ticks it, and the next one unlocks and opens. After the last one the card says so. */
function stepCompleted(
  state: ChecklistState,
  id: StepId,
  source: Source
): ChecklistState {
  if (currentOf(state.done) !== id) {
    return state;
  }
  const done = [...state.done, id];
  const nextId = currentOf(done);
  if (nextId === null) {
    return {
      ...state,
      done,
      openId: null,
      howToId: null,
      view: 'complete',
      completedBy: source,
      spoken: `All ${TOTAL} steps done. ${WORKSPACE.name} is set up`,
    };
  }
  const title = stepOf(id).title;
  const nextTitle = stepOf(nextId).title;
  const spoken = `${title}: done, ${done.length} of ${TOTAL}. Next: ${nextTitle}`;
  return { ...state, done, openId: nextId, howToId: null, spoken };
}

function snoozed(state: ChecklistState): ChecklistState {
  if (state.view !== 'card') {
    return state;
  }
  return { ...state, view: 'pill', spoken: 'Setup guide snoozed' };
}

function resumed(state: ChecklistState): ChecklistState {
  const isPutAway = state.view === 'pill' || state.view === 'gone';
  if (!isPutAway) {
    return state;
  }
  return {
    ...state,
    view: 'card',
    openId: currentOf(state.done),
    howToId: null,
    spoken: 'Setup guide opened',
  };
}

function dismissed(state: ChecklistState): ChecklistState {
  if (state.view === 'gone') {
    return state;
  }
  const spoken = 'Setup guide dismissed. It stays in the top bar';
  return { ...state, view: 'gone', spoken };
}

function completionFaded(
  state: ChecklistState,
  source: Source
): ChecklistState {
  const isShowingMessage = state.view === 'complete';
  const isItsOwn = state.completedBy === source;
  if (!isShowingMessage || !isItsOwn) {
    return state;
  }
  return { ...state, view: 'gone', spoken: '' };
}

export function reducer(
  state: ChecklistState,
  action: ChecklistAction
): ChecklistState {
  switch (action.type) {
    case 'stepToggled':
      return stepToggled(state, action.id);
    case 'howToToggled':
      return howToToggled(state, action.id);
    case 'stepCompleted':
      return stepCompleted(state, action.id, action.source);
    case 'snoozed':
      return snoozed(state);
    case 'resumed':
      return resumed(state);
    case 'dismissed':
      return dismissed(state);
    case 'completionFaded':
      return completionFaded(state, action.source);
  }
}

/** How long the message that everything is done stays before the card fades. */
export const COMPLETE_FOR_MS = 3600;

function completes(after: number, id: StepId): Step {
  return {
    after,
    by: 'demo',
    press: `cta-${id}`,
    action: { type: 'stepCompleted', id, source: 'demo' },
  };
}

/** Two steps are done with their how-to read first: the state the guide rests in. */
const FIRST_STEPS: Step[] = [
  {
    after: 1500,
    by: 'demo',
    press: 'howto-invite',
    action: { type: 'howToToggled', id: 'invite' },
  },
  completes(2300, 'invite'),
];

/**
 * A person does every step, so they are the demonstration's: the guide is snoozed into its pill and
 * brought back, then the last steps are done. The fade that follows is the card's own doing, and it
 * plays even when a person took over while the message was up.
 */
export const SCRIPT: Step[] = [
  ...FIRST_STEPS,
  completes(2000, 'source'),
  { after: 1700, by: 'demo', press: 'snooze', action: { type: 'snoozed' } },
  { after: 1900, by: 'demo', press: 'pill', action: { type: 'resumed' } },
  completes(1500, 'agent'),
  completes(1700, 'run'),
  {
    after: COMPLETE_FOR_MS,
    action: { type: 'completionFaded', source: 'demo' },
  },
];

function endOf(script: Step[]) {
  let state = INITIAL;
  for (const step of script) {
    state = reducer(state, step.action);
  }
  return state;
}

/** Under reduced motion two of five steps are done and the third is open, with its button to press. */
export const RESTING: ChecklistState = { ...endOf(FIRST_STEPS), spoken: '' };

export const LOOP_AFTER_MS = 2200;

